// Dung view-model cho tung khoi giao dien tu MOT trang thai duy nhat va chi gui khi du lieu thay doi
const park = flow.get('park');
if (!park) return null;
const now = Date.now();
const SRC = { card: 'Quẹt thẻ', timeout: 'Tự đóng sau 3 giây', dashboard: 'Dashboard', rule4: 'Rule 4', serial: 'Serial', mqtt: 'MQTT', boot: 'Khởi động' };
const ALERT_SHOW_MS = 30000;
const fmtDur = s => s < 60 ? s + ' giây' : Math.floor(s / 60) + ' phút ' + String(s % 60).padStart(2, '0') + ' giây';
const money = v => Number(v || 0).toLocaleString('vi-VN');
const clock = t => new Date(t).toLocaleTimeString('vi-VN', { hour12: false });

const occupied = park.slots.filter(s => s.uid).length;
const cap = park.capacity;
const g = park.gate;
const openSec = Math.max(0, Math.floor((now - g.since) / 1000));
const gate = {
    open: g.state === 'open',
    blocked: !!g.blocked && g.state === 'open',
    angle: g.angle || (g.state === 'open' ? 90 : 0),
    source: SRC[g.source] || g.source,
    detail: g.state === 'open'
        ? (g.blocked ? 'Có vật cản, tạm hoãn đóng' : (g.mode === 'hold' ? 'Giữ mở theo lệnh · ' + openSec + ' giây' : 'Tự đóng sau 3 giây'))
        : 'Đèn đỏ · sẵn sàng'
};

const overview = {
    occupied: occupied, capacity: cap, free: Math.max(0, cap - occupied), full: occupied >= cap,
    percent: cap ? Math.round(occupied / cap * 100) : 0,
    online: park.online, broker: park.broker, gate: gate,
    revenue: money(park.stats.revenue), checkins: park.stats.checkins, checkouts: park.stats.checkouts
};

const slotsPayload = {
    slots: park.slots.map(s => {
        if (!s.uid) return { slot: s.slot, occupied: false };
        const sec = Math.max(0, Math.floor((now - s.since) / 1000));
        return { slot: s.slot, occupied: true, plate: s.plate, owner: s.owner, timeIn: clock(s.since), duration: fmtDur(sec), overstay: s.warned };
    }),
    capacity: cap
};

const alert = park.alert && now - park.alert.ts < ALERT_SHOW_MS ? park.alert : null;
const controlPayload = { alert: alert, gate: gate, online: park.online };

const st = park.stats;
const statsPayload = {
    avgDuration: st.checkouts ? fmtDur(Math.round(st.durationSec / st.checkouts)) : '—',
    avgFee: st.checkouts ? money(Math.round(st.revenue / st.checkouts)) + ' đ' : '—',
    transactions: park.transactions.length,
    late: park.slots.filter(s => s.warned).length
};

// Chi day thong diep UI cho khoi nao co du lieu thay doi -> khong giat, khong rac WebSocket
const cache = context.get('cache') || {};
const changed = (key, obj) => {
    const s = JSON.stringify(obj);
    if (!msg.forceRender && cache[key] === s) return null;
    cache[key] = s;
    return { payload: obj };
};

// Bieu do: chi day diem moi khi doanh thu hoac so xe thay doi
const last = context.get('last') || {};
let rev = null, occ = null;
if (msg.resetCharts) {
    rev = [{ payload: [] }, { topic: 'Doanh thu', payload: 0 }];
    occ = [{ payload: [] }, { topic: 'Số xe', payload: occupied }];
} else {
    if (last.rev !== st.revenue) rev = { topic: 'Doanh thu', payload: st.revenue };
    if (last.occ !== occupied) occ = { topic: 'Số xe', payload: occupied };
}
context.set('last', { rev: st.revenue, occ: occupied });
const outs = [
    changed('overview', overview),
    changed('slots', slotsPayload),
    changed('control', controlPayload),
    changed('log', park.events),
    changed('stats', statsPayload),
    rev, occ
];
context.set('cache', cache);
return outs;

// Lenh tu nut bam Dashboard -> downlink MQTT (chi ghi bang neu thiet bi offline, tranh trung dong xac nhan)
const park = flow.get('park');
if (!park) return null;
const cmd = msg.payload && msg.payload.cmd;
if (!cmd) return null;
const label = cmd === 'open' ? 'Lệnh mở barie' : 'Lệnh đóng barie';
const ev = park.online
    ? { level: 'info', title: label, text: 'Gửi từ Dashboard qua MQTT', table: false }
    : { level: 'warn', title: label, text: 'ESP32 đang ngoại tuyến, lệnh có thể không được thực hiện', toast: true };
return [{ payload: { cmd: cmd, src: 'dashboard' } }, { events: [ev] }];

const park = flow.get('park');
if (!park) return null;
park.stats = { revenue: 0, checkins: 0, checkouts: 0, durationSec: 0 };
park.transactions = [];
park.events = [];
park.alert = null;
flow.set('park', park);
return { events: [{ level: 'info', title: 'Đặt lại thống kê', text: 'Bắt đầu phiên thống kê mới' }], save: true, resetCharts: true, forceRender: true };

// Khoi phuc thong ke + lich su tu parking_database.json sau khi Node-RED khoi dong lai
const park = flow.get('park');
if (!park) return null;
if (msg.error || typeof msg.payload !== 'string') {
    node.status({ fill: 'grey', shape: 'ring', text: 'chưa có dữ liệu cũ' });
    return { events: [], forceRender: true };
}
try {
    const db = JSON.parse(msg.payload);
    if (db.stats) park.stats = Object.assign(park.stats, db.stats);
    if (Array.isArray(db.transactions)) park.transactions = db.transactions.slice(0, 100);
    if (Array.isArray(db.events)) {
        park.events = db.events.slice(0, 12).map((e, i) => Object.assign({ id: ++park.seq || (i + 1) }, e));
    }
    flow.set('park', park);
    node.status({ fill: 'green', shape: 'dot', text: 'đã khôi phục ' + park.transactions.length + ' giao dịch' });
} catch (e) {
    node.status({ fill: 'red', shape: 'ring', text: 'file hỏng, bỏ qua' });
}
return { events: [], charts: true, forceRender: true };
